    .text

    # Test-only helpers. Students do not edit this file.
    # They deliberately overwrite argument/temporary registers so the caller
    # cannot assume those values survive a function call.

    .globl helper_square
    .type helper_square, @function
helper_square:
    movq %rdi, %rax
    imulq %rdi, %rax
    movq $101, %rcx
    movq $102, %rdx
    movq $103, %rsi
    movq $104, %rdi
    movq $105, %r8
    movq $106, %r9
    movq $107, %r10
    movq $108, %r11
    ret

    .globl helper_affine
    .type helper_affine, @function
helper_affine:
    movq %rdi, %rax
    imulq $3, %rax
    addq $7, %rax
    movq $201, %rcx
    movq $202, %rdx
    movq $203, %rsi
    movq $204, %rdi
    movq $205, %r8
    movq $206, %r9
    movq $207, %r10
    movq $208, %r11
    ret

    .section .note.GNU-stack,"",@progbits
